from __future__ import annotations

import argparse
import json
import os
import sys
from pathlib import Path

from . import config

CALLER = """# Channel Doctor: heals failed runs of this repo's workflows and applies the twice-weekly review's safe
# improvements. Engine and rules: https://github.com/ashivam-dot/channel-doctor (generated by `python -m doctor caller`).
# Stop it with the repository variable DOCTOR_PAUSED=true; DOCTOR_MODE=report keeps it from changing code.
name: doctor

on:
  workflow_run:
    workflows: {workflows}
    types: [completed]
{schedule}  workflow_dispatch:
    inputs:
      mode:
        type: choice
        options: [heal, improve, growth, tidy]
        default: heal
      run_id:
        description: failed run id to heal
        required: false
      dry:
        type: boolean
        default: false

permissions:
  actions: write
  contents: write
  issues: write

jobs:
  doctor:
    if: >-
      vars.DOCTOR_PAUSED != 'true' && (github.event_name != 'workflow_run' ||
      github.event.workflow_run.conclusion == 'failure' || github.event.workflow_run.conclusion == 'timed_out')
    concurrency:
      group: doctor-${{{{ github.event.workflow_run.path || github.event.schedule || github.event_name }}}}
      cancel-in-progress: false
    uses: ashivam-dot/channel-doctor/.github/workflows/doctor.yml@main
    with:
      mode: ${{{{ github.event_name == 'schedule' && (github.event.schedule == '{growth_cron}' && '{daily}' || 'improve') || inputs.mode || 'heal' }}}}
      run_id: ${{{{ format('{{0}}', inputs.run_id || github.event.workflow_run.id) }}}}
      dry: ${{{{ inputs.dry == true }}}}
      report_only: ${{{{ vars.DOCTOR_MODE == 'report' }}}}
    secrets: inherit
"""


IMPROVE_CRON = "23 4 * * 2,5"
GROWTH_CRON = "41 14 * * *"  # before the 15:30 UTC digest


def caller(repo: str) -> str:
    cfg = config.load()
    _, ch, lane = config.lane_for(cfg, repo)
    names = [wf["name"] for wf in lane.get("workflows", {}).values()]
    crons = ([IMPROVE_CRON] if lane.get("mode") == "fix" else []) + ([] if ch.get("drill") else [GROWTH_CRON])
    schedule = "  schedule:\n" + "".join(f'    - cron: "{c}"\n' for c in crons) if crons else ""
    return CALLER.format(workflows=json.dumps(names), schedule=schedule, growth_cron=GROWTH_CRON,
                         daily="growth" if lane.get("analytics") else "tidy")


def selftest() -> int:
    """Report which capabilities are wired, without printing any secret."""
    from .brain import Brain
    from .github import GitHub

    from . import telegram

    wired = bool(os.environ.get("TELEGRAM_BOT_TOKEN") and os.environ.get("TELEGRAM_CHAT_ID"))
    print("telegram:", "configured" if wired else "missing", "| menu:", "set" if wired and telegram.set_menu() else "not set")
    b = Brain()
    if b.ready:
        try:
            from .brain import rank
            top = rank(b.models(), "deep")[:3]
            print("gemini models:", ", ".join(m.split("/")[-1] for m in top) or "none usable")
            res = b.ask_json('Return JSON {"ok": true}', "fast")
            print("gemini generate:", "ok via " + str(b.used) if res and res.get("ok") else "FAILED")
        except Exception as exc:
            print("gemini:", type(exc).__name__)
    else:
        print("gemini: missing key")
    gh = GitHub()
    print("github token:", "present" if gh.token else "missing")
    return 0


def main():
    sys.stdout.reconfigure(line_buffering=True)
    p = argparse.ArgumentParser(prog="doctor")
    sub = p.add_subparsers(dest="cmd", required=True)
    h = sub.add_parser("heal")
    h.add_argument("--repo", default=os.environ.get("GITHUB_REPOSITORY"))
    h.add_argument("--run-id", required=True)
    h.add_argument("--target", default="target")
    h.add_argument("--dry", action="store_true")
    h.add_argument("--report-only", action="store_true")
    i = sub.add_parser("improve")
    i.add_argument("--repo", default=os.environ.get("GITHUB_REPOSITORY"))
    i.add_argument("--target", default="target")
    i.add_argument("--dry", action="store_true")
    i.add_argument("--report-only", action="store_true")
    for name in ("growth", "lab", "tidy"):
        g = sub.add_parser(name)
        g.add_argument("--repo", default=os.environ.get("GITHUB_REPOSITORY"))
        g.add_argument("--dry", action="store_true")
    for name in ("watch", "review", "scout"):
        sub.add_parser(name).add_argument("--dry", action="store_true")
    c = sub.add_parser("caller")
    c.add_argument("repo")
    sub.add_parser("selftest")
    a = p.parse_args()

    if a.cmd in ("heal", "improve"):
        from .heal import Healer
        healer = Healer(a.repo, Path(a.target).resolve(), a.dry, a.report_only)
        healer.heal(a.run_id) if a.cmd == "heal" else healer.improve()
    elif a.cmd == "growth":
        from .growth import run_repo
        run_repo(a.repo, a.dry)
    elif a.cmd == "lab":
        from .lab import run_repo
        run_repo(a.repo, config.load(), a.dry)
    elif a.cmd == "tidy":
        from .tidy import run_repo
        run_repo(a.repo, a.dry)
    elif a.cmd == "watch":
        from .watch import main as run
        run(a.dry)
    elif a.cmd == "review":
        from .review import main as run
        run(a.dry)
    elif a.cmd == "scout":
        from .scout import main as run
        run(a.dry)
    elif a.cmd == "caller":
        print(caller(a.repo), end="")
    elif a.cmd == "selftest":
        raise SystemExit(selftest())


if __name__ == "__main__":
    main()
